import{_ as l,a0 as d,w as o,s as c,ao as p,I as t,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Git 倉庫中，文件究竟被存儲在哪裏？ | LCTT x X-CMD","titleTemplate":false,"description":"在 Git 倉庫中，文件究竟被存儲在哪裏？ | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Git 倉庫中，文件究竟被存儲在哪裏？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Git 倉庫中，文件究竟被存儲在哪裏？ | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230914 In a git repository, where do your files live","title":"在 Git 倉庫中，文件究竟被存儲在哪裏？","tag":"202309","desc":""},"relativePath":"202309/20230914 In a git repository, where do your files live.md","filePath":"[post].md"}'),b={name:"202309/20230914 In a git repository, where do your files live.md"};function r(g,s,h,f,k,u){const e=d("Link");return o(),c("div",null,[s[26]||(s[26]=p(`<h1 id="在-git-倉庫中-文件究竟被存儲在哪裏" tabindex="-1">在 Git 倉庫中，文件究竟被存儲在哪裏？ <a class="header-anchor" href="#在-git-倉庫中-文件究竟被存儲在哪裏" aria-label="Permalink to “在 Git 倉庫中，文件究竟被存儲在哪裏？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/16/230138n1j44qiabgplgbw4.jpg" alt=""></p><p>大家好！今天我和一個朋友討論 Git 的工作原理，我們感到奇怪，Git 是如何存儲你的文件的？我們知道它存儲在 <code>.git</code> 目錄中，但具體到 <code>.git</code> 中的哪個位置，各個版本的歷史文件又被存儲在哪裏呢？</p><p>以這個Blog為例，其文件存儲在一個 Git 倉庫中，其中有一個文件名為 <code>content/post/2019-06-28-brag-doc.markdown</code>。這個文件在我的 <code>.git</code> 文件夾中具體的位置在哪裏？過去的文件版本又被存儲在哪裏？那麼，就讓我們通過編寫一些簡短的 Python 代碼來探尋答案吧。</p><h3 id="git-把文件存儲在-git-objects-之中" tabindex="-1">Git 把文件存儲在 .git/objects 之中 <a class="header-anchor" href="#git-把文件存儲在-git-objects-之中" aria-label="Permalink to “Git 把文件存儲在 .git/objects 之中”">​</a></h3><p>你的倉庫中，每一個文件的歷史版本都被儲存在 <code>.git/objects</code> 中。比如，對於這個Blog，<code>.git/objects</code> 包含了 2700 多個文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find .git/objects/ -type f | wc -l</span></span>
<span class="line"><span>2761</span></span></code></pre></div><blockquote><p>注意：<code>.git/objects</code> 包含的信息，不僅僅是 “倉庫中每一個文件的所有先前版本”，但我們暫不詳細討論這一內容。</p></blockquote>`,8)),t("p",null,[s[1]||(s[1]=a("這裏是一個簡短的 Python 程序（",-1)),n(e,{href:"https://gist.github.com/jvns/ff884dceef7660402fe1eca697cfbf51"},{default:i(()=>[...s[0]||(s[0]=[a("find-git-object.py",-1)])]),_:1}),s[2]||(s[2]=a("），它可以幫助我們定位在 ",-1)),s[3]||(s[3]=t("code",null,".git/objects",-1)),s[4]||(s[4]=a(" 中的特定文件的具體位置。",-1))]),s[27]||(s[27]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import hashlib</span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def object_path(content):</span></span>
<span class="line"><span>    header = f&quot;blob {len(content)}\\0&quot;</span></span>
<span class="line"><span>    data = header.encode() + content</span></span>
<span class="line"><span>    sha1 = hashlib.sha1()</span></span>
<span class="line"><span>    sha1.update(data)</span></span>
<span class="line"><span>    digest = sha1.hexdigest()</span></span>
<span class="line"><span>    return f&quot;.git/objects/{digest[:2]}/{digest[2:]}&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>with open(sys.argv[1], &quot;rb&quot;) as f:</span></span>
<span class="line"><span>    print(object_path(f.read()))</span></span></code></pre></div><p>此程序的主要操作如下：</p><ul><li>讀取文件內容</li><li>計算一個頭部（<code>blob 16673\\0</code>），並將其與文件內容合併</li><li>計算出文件的 sha1 校驗和（此處為 <code>e33121a9af82dd99d6d706d037204251d41d54</code>）</li><li>將這個 sha1 校驗和轉換為路徑（如 <code>.git/objects/e3/3121a9af82dd99d6d706d037204251d41d54</code>）</li></ul><p>運行的方法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 find-git-object.py content/post/2019-06-28-brag-doc.markdown</span></span>
<span class="line"><span>.git/objects/8a/e33121a9af82dd99d6d706d037204251d41d54</span></span></code></pre></div><h3 id="術語解釋-內容尋址存儲" tabindex="-1">術語解釋：“內容尋址存儲” <a class="header-anchor" href="#術語解釋-內容尋址存儲" aria-label="Permalink to “術語解釋：“內容尋址存儲””">​</a></h3><p>這種存儲策略的術語為“<ruby>內容尋址存儲<rt>content addressed storage</rt></ruby>”，它指的是對象在資料庫中的文件名與文件內容的哈希值相同。</p><p>內容尋址存儲的有趣之處就是，假設我有兩份或許多份內容完全相同的文件，在 Git 的資料庫中，並不會因此佔用額外空間。如果內容的哈希值是 <code>aabbbbbbbbbbbbbbbbbbbbbbbbb</code>，它們都會被存儲在 <code>.git/objects/aa/bbbbbbbbbbbbbbbbbbbbb</code> 中。</p><h3 id="這些對象是如何進行編碼的" tabindex="-1">這些對象是如何進行編碼的？ <a class="header-anchor" href="#這些對象是如何進行編碼的" aria-label="Permalink to “這些對象是如何進行編碼的？”">​</a></h3><p>如果我嘗試在 <code>.git/objects</code> 目錄下查看這個文件，顯示的內容似乎有一些奇怪：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/objects/8a/e33121a9af82dd99d6d706d037204251d41d54</span></span>
<span class="line"><span>x^A&lt;8D&gt;&lt;9B&gt;}s&lt;E3&gt;Ƒ&lt;C6&gt;&lt;EF&gt;o|&lt;8A&gt;^Q&lt;9D&gt;&lt;EC&gt;ju&lt;92&gt;&lt;E8&gt;&lt;DD&gt;&lt;9C&gt;&lt;9C&gt;*&lt;89&gt;j&lt;FD&gt;^...</span></span></code></pre></div><p>這是怎麼回事呢？讓我們來運行 <code>file</code> 命令檢查一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file .git/objects/8a/e33121a9af82dd99d6d706d037204251d41d54</span></span>
<span class="line"><span>.git/objects/8a/e33121a9af82dd99d6d706d037204251d41d54: zlib compressed data</span></span></code></pre></div><p>原來，它是壓縮的！我們可以編寫一個小巧的 Python 程序—— <code>decompress.py</code>，然後用 <code>zlib</code> 模組去解壓這些數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import zlib</span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>with open(sys.argv[1], &quot;rb&quot;) as f:</span></span>
<span class="line"><span>    content = f.read()</span></span>
<span class="line"><span>    print(zlib.decompress(content).decode())</span></span></code></pre></div><p>讓我們來解壓一下看看結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 decompress.py .git/objects/8a/e33121a9af82dd99d6d706d037204251d41d54</span></span>
<span class="line"><span>blob 16673---</span></span>
<span class="line"><span>title: &quot;Get your work recognized: write a brag document&quot;</span></span>
<span class="line"><span>date: 2019-06-28T18:46:02Z</span></span>
<span class="line"><span>url: /blog/brag-documents/</span></span>
<span class="line"><span>categories: []</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>... the entire blog post ...</span></span></code></pre></div><p>結果顯示，這些數據的編碼方式非常簡單：首先有 <code>blob 16673\\0</code> 標識，其後就是文件的全部內容。</p><h3 id="這裏並沒有差異性數據-diff" tabindex="-1">這裏並沒有差異性數據（diff） <a class="header-anchor" href="#這裏並沒有差異性數據-diff" aria-label="Permalink to “這裏並沒有差異性數據（diff）”">​</a></h3><p>這裏有一件我第一次知道時讓我感到驚訝的事：這裏並沒有任何差異性數據！那個文件是該篇Blog文章的第 9 個版本，但 Git 在 <code>.git/objects</code> 目錄中存儲的版本是完整文件內容，而並非與前一版本的差異。</p>`,20)),t("p",null,[s[6]||(s[6]=a("儘管 Git 實際上有時候會以差異性數據存儲文件（例如，當你運行 ",-1)),s[7]||(s[7]=t("code",null,"git gc",-1)),s[8]||(s[8]=a(" 時，為了提升效率，它可能會將多個不同的文件封裝成 “打包文件”），但在我個人經驗中，我從未需要關注這個細節，所以我們不在此深入討論。然而，關於這種格式如何工作，Aditya Mukerjee 有篇優秀的文章 《",-1)),n(e,{href:"https://codewords.recurse.com/issues/three/unpacking-git-packfiles"},{default:i(()=>[...s[5]||(s[5]=[a("拆解 Git 的打包文件",-1)])]),_:1}),s[9]||(s[9]=a("》。",-1))]),s[28]||(s[28]=p(`<h3 id="blog文章的舊版本在哪" tabindex="-1">Blog文章的舊版本在哪？ <a class="header-anchor" href="#blog文章的舊版本在哪" aria-label="Permalink to “Blog文章的舊版本在哪？”">​</a></h3><p>你可能會好奇：如果在我修復了一些錯別字之前，這篇博文已經存在了 8 個版本，那它們在 <code>.git/objects</code> 目錄中的位置是哪裏？我們如何找到它們呢？</p><p>首先，我們來使用 <code>git log</code> 命令來查找改動過這個文件的每一個提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline  content/post/2019-06-28-brag-doc.markdown</span></span>
<span class="line"><span>c6d4db2d</span></span>
<span class="line"><span>423cd76a</span></span>
<span class="line"><span>7e91d7d0</span></span>
<span class="line"><span>f105905a</span></span>
<span class="line"><span>b6d23643</span></span>
<span class="line"><span>998a46dd</span></span>
<span class="line"><span>67a26b04</span></span>
<span class="line"><span>d9999f17</span></span>
<span class="line"><span>026c0f52</span></span>
<span class="line"><span>72442b67</span></span></code></pre></div><p>然後，我們選擇一個之前的提交，比如 <code>026c0f52</code>。提交也被存儲在 <code>.git/objects</code> 中，我們可以嘗試在那裏找到它。但是失敗了！因為 <code>ls .git/objects/02/6c*</code> 沒有顯示任何內容！如果有人告訴你，“我們知道有時 Git 會打包對象來節省空間，我們並不需過多關心它”，但現在，我們需要去面對這個問題了。</p><p>那就讓我們去解決它吧。</p><h3 id="讓我們開始解包一些對象" tabindex="-1">讓我們開始解包一些對象 <a class="header-anchor" href="#讓我們開始解包一些對象" aria-label="Permalink to “讓我們開始解包一些對象”">​</a></h3><p>現在我們需要從打包文件中解包出一些對象。我在 Stack Overflow 上查找了一下，看起來我們可以這樣進行操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv .git/objects/pack/pack-adeb3c14576443e593a3161e7e1b202faba73f54.pack .</span></span>
<span class="line"><span>$ git unpack-objects &lt; pack-adeb3c14576443e593a3161e7e1b202faba73f54.pack</span></span></code></pre></div><p>這種直接對庫進行手術式的做法讓人有些緊張，但如果我誤操作了，我還可以從 Github 上重新克隆這個庫，所以我並不太擔心。</p><p>解包所有的對象文件後，我們得到了更多的對象：大約有 20000 個，而不是原來的大約 2700 個。看起來很酷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find .git/objects/ -type f | wc -l</span></span>
<span class="line"><span>20138</span></span></code></pre></div><h3 id="我們回頭再看看提交" tabindex="-1">我們回頭再看看提交 <a class="header-anchor" href="#我們回頭再看看提交" aria-label="Permalink to “我們回頭再看看提交”">​</a></h3><p>現在我們可以繼續看看我們的提交 <code>026c0f52</code>。我們之前説過 <code>.git/objects</code> 中並不都是文件，其中一部分是提交！為了弄清楚我們的舊文章 <code>content/post/2019-06-28-brag-doc.markdown</code> 是在哪裏被保存的，我們需要深入查看這個提交。</p><p>首先，我們需要在 <code>.git/objects</code> 中查看這個提交。</p><h3 id="查看提交的第一步-找到提交" tabindex="-1">查看提交的第一步：找到提交 <a class="header-anchor" href="#查看提交的第一步-找到提交" aria-label="Permalink to “查看提交的第一步：找到提交”">​</a></h3><p>經過解包後，我們現在可以在 <code>.git/objects/02/6c0f5208c5ea10608afc9252c4a56c1ac1d7e4</code> 中找到提交 <code>026c0f52</code>，我們可以用下面的方法去查看它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 decompress.py .git/objects/02/6c0f5208c5ea10608afc9252c4a56c1ac1d7e4</span></span>
<span class="line"><span>commit 211tree 01832a9109ab738dac78ee4e95024c74b9b71c27</span></span>
<span class="line"><span>parent 72442b67590ae1fcbfe05883a351d822454e3826</span></span>
<span class="line"><span>author Julia Evans &lt;julia@jvns.ca&gt; 1561998673 -0400</span></span>
<span class="line"><span>committer Julia Evans &lt;julia@jvns.ca&gt; 1561998673 -0400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>brag doc</span></span></code></pre></div><p>我們也可以用 <code>git cat-file -p 026c0f52</code> 命令來獲取相同的信息，這個命令能起到相同的作用，但是它在格式化數據時做得更好一些。（<code>-p</code> 選項意味着它能夠以更友好的方式進行格式化）</p><h3 id="查看提交的第二步-找到樹" tabindex="-1">查看提交的第二步：找到樹 <a class="header-anchor" href="#查看提交的第二步-找到樹" aria-label="Permalink to “查看提交的第二步：找到樹”">​</a></h3><p>這個提交包含一個<strong>樹</strong>。樹是什麼呢？讓我們看一下。樹的 ID 是 <code>01832a9109ab738dac78ee4e95024c74b9b71c27</code>，我們可以使用先前的 <code>decompress.py</code> 腳本查看這個 Git 對象，儘管我不得不移除 <code>.decode()</code> 才能避免腳本崩潰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 decompress.py .git/objects/01/832a9109ab738dac78ee4e95024c74b9b71c27</span></span></code></pre></div><p>這個輸出的格式有些難以閲讀。主要的問題在於，該提交的哈希（<code>\\xc3\\xf7$8\\x9b\\x8dO\\x19/\\x18\\xb7}|\\xc7\\xce\\x8e…</code>）是原始字節，而沒有進行十六進制的編碼，因此我們看到 <code>\\xc3\\xf7$8\\x9b\\x8d</code> 而非 <code>c3f76024389b8d</code>。我打算切換至 <code>git cat-file -p</code> 命令，它能以更友好的方式顯示數據，我不想自己編寫一個解析器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cat-file -p 01832a9109ab738dac78ee4e95024c74b9b71c27</span></span>
<span class="line"><span>100644 blob c3f76024389b8d4f192f18b77d7cc7ce8e3a68ad	.gitignore</span></span>
<span class="line"><span>100644 blob 7ebaecb311a05e1ca9a43f1eb90f1c6647960bc1	README.md</span></span>
<span class="line"><span>100644 blob 0f21dc9bf1a73afc89634bac586271384e24b2c9	Rakefile</span></span>
<span class="line"><span>100644 blob 00b9d54abd71119737d33ee5d29d81ebdcea5a37	config.yaml</span></span>
<span class="line"><span>040000 tree 61ad34108a327a163cdd66fa1a86342dcef4518e	content &lt;-- 這是我們接下來的目標</span></span>
<span class="line"><span>040000 tree 6d8543e9eeba67748ded7b5f88b781016200db6f	layouts</span></span>
<span class="line"><span>100644 blob 22a321a88157293c81e4ddcfef4844c6c698c26f	mystery.rb</span></span>
<span class="line"><span>040000 tree 8157dc84a37fca4cb13e1257f37a7dd35cfe391e	scripts</span></span>
<span class="line"><span>040000 tree 84fe9c4cb9cef83e78e90a7fbf33a9a799d7be60	static</span></span>
<span class="line"><span>040000 tree 34fd3aa2625ba784bced4a95db6154806ae1d9ee	themes</span></span></code></pre></div><p>這是我在這次提交時庫的根目錄中所有的文件。看起來我曾經不小心提交了一個名為 <code>mystery.rb</code> 的文件，後來我刪除了它。</p><p>我們的文件在 <code>content</code> 目錄中，接下來讓我們看看那個樹：<code>61ad34108a327a163cdd66fa1a86342dcef4518e</code></p><h3 id="查看提交的第三步-又一棵樹" tabindex="-1">查看提交的第三步：又一棵樹 <a class="header-anchor" href="#查看提交的第三步-又一棵樹" aria-label="Permalink to “查看提交的第三步：又一棵樹”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cat-file -p 61ad34108a327a163cdd66fa1a86342dcef4518e</span></span>
<span class="line"><span>040000 tree 1168078878f9d500ea4e7462a9cd29cbdf4f9a56    about</span></span>
<span class="line"><span>100644 blob e06d03f28d58982a5b8282a61c4d3cd5ca793005    newsletter.markdown</span></span>
<span class="line"><span>040000 tree 1f94b8103ca9b6714614614ed79254feb1d9676c    post &lt;-- 我們接下來的目標！</span></span>
<span class="line"><span>100644 blob 2d7d22581e64ef9077455d834d18c209a8f05302    profiler-project.markdown</span></span>
<span class="line"><span>040000 tree 06bd3cee1ed46cf403d9d5a201232af5697527bb    projects</span></span>
<span class="line"><span>040000 tree 65e9357973f0cc60bedaa511489a9c2eeab73c29    talks</span></span>
<span class="line"><span>040000 tree 8a9d561d536b955209def58f5255fc7fe9523efd    zines</span></span></code></pre></div><p>還未結束……</p><h3 id="查看提交的第四步-更多的樹" tabindex="-1">查看提交的第四步：更多的樹…… <a class="header-anchor" href="#查看提交的第四步-更多的樹" aria-label="Permalink to “查看提交的第四步：更多的樹……”">​</a></h3><p>我們要尋找的文件位於 <code>post/</code> 目錄，因此我們需要進一步探索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cat-file -p 1f94b8103ca9b6714614614ed79254feb1d9676c</span></span>
<span class="line"><span>.... 省略了大量行 ...</span></span>
<span class="line"><span>100644 blob 170da7b0e607c4fd6fb4e921d76307397ab89c1e    2019-02-17-organizing-this-blog-into-categories.markdown</span></span>
<span class="line"><span>100644 blob 7d4f27e9804e3dc80ab3a3912b4f1c890c4d2432    2019-03-15-new-zine--bite-size-networking-.markdown</span></span>
<span class="line"><span>100644 blob 0d1b9fbc7896e47da6166e9386347f9ff58856aa    2019-03-26-what-are-monoidal-categories.markdown</span></span>
<span class="line"><span>100644 blob d6949755c3dadbc6fcbdd20cc0d919809d754e56    2019-06-23-a-few-debugging-resources.markdown</span></span>
<span class="line"><span>100644 blob 3105bdd067f7db16436d2ea85463755c8a772046    2019-06-28-brag-doc.markdown &lt;-- 我們找到了！！！</span></span></code></pre></div><p>在此，<code>2019-06-28-brag-doc.markdown</code> 之所以位於列表最後，是因為在發佈時它是最新的博文。</p><h3 id="查看提交的第五步-我們終於找到它" tabindex="-1">查看提交的第五步：我們終於找到它！ <a class="header-anchor" href="#查看提交的第五步-我們終於找到它" aria-label="Permalink to “查看提交的第五步：我們終於找到它！”">​</a></h3><p>經過努力，我們找到了博文歷史版本所在的對象文件！太棒了！它的哈希值是 <code>3105bdd067f7db16436d2ea85463755c8a772046</code>，因此它位於 <code>git/objects/31/05bdd067f7db16436d2ea85463755c8a772046</code>。</p><p>我們可以使用 <code>decompress.py</code> 來查看它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 decompress.py .git/objects/31/05bdd067f7db16436d2ea85463755c8a772046 | head</span></span>
<span class="line"><span>blob 15924---</span></span>
<span class="line"><span>title: &quot;Get your work recognized: write a brag document&quot;</span></span>
<span class="line"><span>date: 2019-06-28T18:46:02Z</span></span>
<span class="line"><span>url: /blog/brag-documents/</span></span>
<span class="line"><span>categories: []</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>... 文件的剩餘部分在此 ...</span></span></code></pre></div><p>這就是博文的舊版本！如果我執行命令 <code>git checkout 026c0f52 content/post/2019-06-28-brag-doc.markdown</code> 或者 <code>git restore --source 026c0f52 content/post/2019-06-28-brag-doc.markdown</code>，我就會獲取到這個版本。</p><h3 id="這樣遍歷樹就是-git-log-的運行機制" tabindex="-1">這樣遍歷樹就是 git log 的運行機制 <a class="header-anchor" href="#這樣遍歷樹就是-git-log-的運行機制" aria-label="Permalink to “這樣遍歷樹就是 git log 的運行機制”">​</a></h3><p>我們剛剛經歷的整個過程（找到提交、逐層遍歷目錄樹、搜索所需文件名）看似繁瑣，但實際上當我們執行 <code>git log content/post/2019-06-28-brag-doc.markdown</code> 時，背後就是這樣在運行。它需要逐個檢查你歷史記錄中的每一個提交，在每個提交中核查 <code>content/post/2019-06-28-brag-doc.markdown</code> 的版本（例如在這個案例中為 <code>3105bdd067f7db16436d2ea85463755c8a772046</code>），並查看它是否自上一提交以來有所改變。</p><p>這就是為什麼有時 <code>git log FILENAME</code> 會執行的有些緩慢 —— 我的這個倉庫中有 3000 個提交，它需要對每個提交做大量的工作，來判斷該文件是否在該提交中發生過變化。</p><h3 id="我有多少個歷史版本的文件" tabindex="-1">我有多少個歷史版本的文件？ <a class="header-anchor" href="#我有多少個歷史版本的文件" aria-label="Permalink to “我有多少個歷史版本的文件？”">​</a></h3><p>目前，我在我的Blog倉庫中跟蹤了 1530 個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git ls-files | wc -l</span></span>
<span class="line"><span>1530</span></span></code></pre></div><p>但歷史文件有多少呢？我們可以列出 <code>.git/objects</code> 中所有的內容，看看有多少對象文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find .git/objects/ -type f | grep -v pack | awk -F/ &#39;{print $3 $4}&#39; | wc -l</span></span>
<span class="line"><span>20135</span></span></code></pre></div><p>但並不是所有這些都代表過去版本的文件 —— 正如我們之前所見，許多都是提交和目錄樹。不過，我們可以編寫一個小小的 Python 腳本 <code>find-blobs.py</code>，遍歷所有對象並檢查是否以 <code>blob</code> 開頭：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import zlib</span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for line in sys.stdin:</span></span>
<span class="line"><span>    line = line.strip()</span></span>
<span class="line"><span>    filename = f&quot;.git/objects/{line[0:2]}/{line[2:]}&quot;</span></span>
<span class="line"><span>    with open(filename, &quot;rb&quot;) as f:</span></span>
<span class="line"><span>        contents = zlib.decompress(f.read())</span></span>
<span class="line"><span>        if contents.startswith(b&quot;blob&quot;):</span></span>
<span class="line"><span>            print(line)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find .git/objects/ -type f | grep -v pack | awk -F/ &#39;{print $3 $4}&#39; | python3 find-blobs.py | wc -l</span></span>
<span class="line"><span>6713</span></span></code></pre></div><p>於是，看起來在我的 Git 倉庫中存放的舊文件版本有 <code>6713 - 1530 = 5183</code> 個，Git 會為我保存這些文件，以備我想着要恢復它們時使用。太好了！</p><h3 id="就這些啦" tabindex="-1">就這些啦！ <a class="header-anchor" href="#就這些啦" aria-label="Permalink to “就這些啦！”">​</a></h3>`,51)),t("p",null,[s[11]||(s[11]=a("在 ",-1)),n(e,{href:"https://gist.github.com/jvns/ff884dceef7660402fe1eca697cfbf51"},{default:i(()=>[...s[10]||(s[10]=[a("這個 gist",-1)])]),_:1}),s[12]||(s[12]=a(" 中附上了全部的此篇文章所用代碼，其實沒多少。",-1))]),s[29]||(s[29]=p(`<p>我以為我已經對 Git 的工作方式瞭如指掌，但我以前從未真正涉及過打包文件，所以這次探索很有趣。我也很少思考當我讓 <code>git log</code> 跟蹤一個文件的歷史時，它實際上有多大的工作量，因此也很開心能深入研究這個。</p><p>作為一個有趣的後續：我提交這篇博文後，Git 就警告我倉庫中的對象太多（我猜 20,000 太多了！），並運行 <code>git gc</code> 將它們全部壓縮成打包文件。所以現在我的 <code>.git/objects</code> 目錄已經被壓縮得十分小了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find .git/objects/ -type f | wc -l</span></span>
<span class="line"><span>14</span></span></code></pre></div><p><em>（題圖：MJ/319a396c-6f3f-4891-b051-261312c8ea9a）</em></p><hr>`,5)),t("p",null,[s[14]||(s[14]=a("via: ",-1)),n(e,{href:"https://jvns.ca/blog/2023/09/14/in-a-git-repository--where-do-your-files-live-/"},{default:i(()=>[...s[13]||(s[13]=[a("https://jvns.ca/blog/2023/09/14/in-a-git-repository--where-do-your-files-live-/",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=a("作者：",-1)),n(e,{href:"https://jvns.ca/"},{default:i(()=>[...s[15]||(s[15]=[a("Julia Evans",-1)])]),_:1}),s[19]||(s[19]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[16]||(s[16]=[a("lujun9972",-1)])]),_:1}),s[20]||(s[20]=a(" 譯者：ChatGPT 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[23]||(s[23]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[22]||(s[22]=[a("Linux中國",-1)])]),_:1}),s[25]||(s[25]=a(" 榮譽推出",-1))])])}const v=l(b,[["render",r]]);export{C as __pageData,v as default};
